using Godot;

namespace TIndustry.Godot;

/// <summary>
/// Single entry point for sprite textures: <c>res://assets/{id}.png</c>, where the id is the one in
/// <c>data/content.json</c> (parts use a suffix, animations are <c>{id}-anim.png</c> strips).
/// Sprites are generated by <c>tools/art/genera.py</c>.
/// </summary>
public static class Sprites
{
    private static readonly Dictionary<string, Texture2D?> Cache = new(StringComparer.Ordinal);
    private static readonly Dictionary<string, Texture2D[]> FrameCache = new(StringComparer.Ordinal);
    private static readonly HashSet<string> Warned = new(StringComparer.Ordinal);
    private static Texture2D? _placeholder;

    /// <summary>Texture of <paramref name="id"/>; a magenta placeholder (and a warning) when the PNG is missing.</summary>
    public static Texture2D For(string id)
    {
        if (TryFor(id) is { } tex)
        {
            return tex;
        }

        if (Warned.Add(id))
        {
            GD.PushWarning($"Sprites: manca res://assets/{id}.png");
        }

        return _placeholder ??= Placeholder();
    }

    /// <summary>Texture of <paramref name="id"/>, or null when there is no PNG (callers that hide the icon).</summary>
    public static Texture2D? TryFor(string id)
    {
        if (!Cache.TryGetValue(id, out var tex))
        {
            var path = $"res://assets/{id}.png";
            tex = ResourceLoader.Exists(path) ? GD.Load<Texture2D>(path) : null;
            Cache[id] = tex;
        }

        return tex;
    }

    /// <summary>Large item icon (HUD, panels).</summary>
    public static Texture2D Item(string itemId) => For(itemId);

    /// <summary>Small item sprite drawn on belts; falls back to the large icon.</summary>
    public static Texture2D BeltItem(string itemId) => TryFor(itemId + "-belt") ?? Item(itemId);

    /// <summary>Frames of the <c>{id}-anim.png</c> strip: square frames, side = strip height.</summary>
    public static Texture2D[] Frames(string id)
    {
        if (FrameCache.TryGetValue(id, out var frames))
        {
            return frames;
        }

        var strip = For(id + "-anim");
        var side = strip.GetHeight();
        var count = Math.Max(1, strip.GetWidth() / side);
        frames = new Texture2D[count];
        for (var i = 0; i < count; i++)
        {
            frames[i] = new AtlasTexture { Atlas = strip, Region = new Rect2(i * side, 0, side, side) };
        }

        FrameCache[id] = frames;
        return frames;
    }

    /// <summary>Scale that makes <paramref name="tex"/> span <paramref name="cells"/> world cells.</summary>
    public static float ScaleToCells(Texture2D tex, int cells, int tileSize) => cells * tileSize / (float)tex.GetWidth();

    private static Texture2D Placeholder()
    {
        var image = Image.CreateEmpty(32, 32, false, Image.Format.Rgba8);
        image.Fill(Colors.Magenta);
        return ImageTexture.CreateFromImage(image);
    }
}
